let text = $json.candidates[0].content.parts[0].text;

// remove markdown code blocks
text = text.replace(/```json/g, '').replace(/```/g, '').trim();

const parsed = JSON.parse(text);

return {
  json: parsed
};

const sql = $json.sql_plan.queries[0].sql;

let errors = [];

if (!sql) {
  errors.push("empty_sql");
}

if (!/^\s*SELECT\b/i.test(sql)) {
  errors.push("query_must_start_with_SELECT");
}

if (/--|\/\*/.test(sql)) {
  errors.push("sql_comments_not_allowed");
}

if (/\b(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|TRUNCATE|GRANT|REVOKE)\b/i.test(sql)) {
  errors.push("dangerous_sql_keyword_detected");
}

if (!/\b(pos|inventory|forecasting)\./.test(sql)) {
  errors.push("unknown_schema_used");
}

return {
  validated: errors.length === 0,
  sql: sql,
  errors: errors
};

const rows = $input.all()
  .map(item => item.json)
  .filter(r => Object.keys(r).length > 0); // remove {}

if (rows.length === 0) {
  return [
    {
      json: {
        sql_rows_text: "No matching records found for the requested period.",
        row_count: 0
      }
    }
  ];
}

const text = rows
  .map((r, i) => `${i + 1}. ${r.productName} (SKU: ${r.sku}) sold ${r.total_quantity_sold}`)
  .join('\n');

return [
  {
    json: {
      sql_rows_text: text,
      row_count: rows.length
    }
  }
];

