const input = $input.first().json;

const components = input.components || [];

const grouped = {};

for (const c of components) {
  const key = `${c.name}_${c.value_or_part}_${c.package}`;

  if (!grouped[key]) {
    grouped[key] = {
      category: c.category,
      name: c.name,
      qty: 0,
      value_or_part: c.value_or_part,
      package: c.package,
      notes: c.notes
    };
  }

  grouped[key].qty += Number(c.qty || 1);
}

input.components = Object.values(grouped)
.sort((a, b) => a.category.localeCompare(b.category));

return [{ json: input }];

const data = $input.first().json;

let md = `# ${data.project_title}\n\n`;

md += `## Project Summary\n${data.project_summary}\n\n`;

if (data.assumptions?.length) {
  md += `## Assumptions\n`;
  data.assumptions.forEach(a => {
    md += `- ${a}\n`;
  });
  md += `\n`;
}

md += `## Complete BOM\n\n`;

for (const c of data.components) {
  md += `- ${c.name} | ${c.value_or_part} | Qty: ${c.qty} | ${c.package} | ${c.notes}\n`;
}

if (data.unknowns?.length) {
  md += `\n## Unknowns\n`;
  data.unknowns.forEach(u => {
    md += `- ${u}\n`;
  });
}

return [{ json: { response: md, raw: data } }];

const output = $input.first().json.output;

// Remove the [READY_TO_GENERATE] token from the output
const cleaned = output.replace(/\[READY_TO_GENERATE\]/gi, '').trim();

// Extract the table rows from the markdown table
const lines = cleaned.split('\n');
const rows = [];
let inTable = false;
let projectTitle = 'Unknown Project';

for (const line of lines) {
  if (line.startsWith('**Complete Component List for:')) {
    projectTitle = line.replace('**Complete Component List for:', '').replace('**', '').trim();
  }
  if (line.startsWith('|') && !line.startsWith('|---') && !line.startsWith('| #')) {
    inTable = true;
    const cols = line.split('|').map(c => c.trim()).filter(c => c.length > 0);
    if (cols.length >= 4) {
      rows.push({
        json: {
          project_title: projectTitle,
          serial_no: cols[0],
          component_name: cols[1],
          value_spec: cols[2],
          quantity: cols[3],
          notes: cols[4] || '',
          generated_at: new Date().toISOString()
        }
      });
    }
  }
}

if (rows.length === 0) {
  // Fallback: return full output as single row
  return [{
    json: {
      project_title: projectTitle,
      serial_no: '1',
      component_name: 'Full Output (parse failed)',
      value_spec: cleaned,
      quantity: '-',
      notes: 'Please check the format',
      generated_at: new Date().toISOString()
    }
  }];
}

return rows;
